#Requires -Version 5.1
#Requires -RunAsAdministrator
<#
.SYNOPSIS
Przygotowuje wzorzec Windows 11 dla NovaLab Start, bez pobierania danych.
.DESCRIPTION
Skrypt zawiera kompletny pakiet cwiczen jako archiwum Base64 na koncu pliku.
Tworzy user01-user06 (konta standardowe) i szesc kont WEB, wspolne dane i SMB.
Wzorzec otrzymuje 10.60.0.254/24 bez bramy; porty labu sa zablokowane do
uruchomienia Finalize-Clone.ps1 na klonie. Konta Kali nie sa modyfikowane.
Python 3.11+ x64 musi byc dostepny dla wszystkich uzytkownikow. Opcjonalnie
mozna wskazac podpisany, klasyczny instalator python-3.x-amd64.exe offline.
Sysprep i wylaczenie nastapia tylko po podaniu odpowiedniego przelacznika.
.EXAMPLE
powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\Przygotuj-Wzorzec.ps1 -IsolatedLabVM -CheckOnly
.EXAMPLE
powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\Przygotuj-Wzorzec.ps1 -IsolatedLabVM -SysprepShutdown
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][switch]$IsolatedLabVM,
    [string]$LabAdapterName,
    [string]$PythonExe,
    [string]$PythonInstallerPath,
    [switch]$CheckOnly,
    [switch]$SysprepShutdown,
    [switch]$ShutdownWhenReady
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$labRoot = Join-Path $env:ProgramData 'NovaLabStart'
$stage = Join-Path $env:SystemDrive 'LabPackages\NovaLabStart-Master-3_1'
