function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant() }
    finally { $sha.Dispose() }
}

function Test-Python([string]$Candidate) {
    if (-not $Candidate -or -not (Test-Path -LiteralPath $Candidate -PathType Leaf)) { return $null }
    if ($Candidate -match '\\WindowsApps\\|\\Users\\') { return $null }
    try {
        $raw = @(& $Candidate -c 'import sys,struct; print(sys.executable); print(sys.version.split()[0]); print(int(sys.version_info>=(3,11) and struct.calcsize(chr(80))==8))' 2>$null)
        if ($LASTEXITCODE -ne 0) { return $null }
        if ($raw.Count -eq 3 -and $raw[2] -eq '1') { return [pscustomobject]@{ok=$true;exe=$raw[0];version=$raw[1]} }
    } catch { return $null }
    return $null
}

function Find-Python {
    $candidates = @()
    if ($PythonExe) { $candidates += $PythonExe }
    $cmd = Get-Command python.exe -ErrorAction SilentlyContinue
    if ($cmd) { $candidates += $cmd.Source }
    $candidates += (Join-Path $env:ProgramFiles 'NovaLabPython\python.exe')
    $dirs = @(Get-ChildItem -LiteralPath $env:ProgramFiles -Directory -Filter 'Python*' -ErrorAction SilentlyContinue)
    foreach ($directory in $dirs) { $candidates += (Join-Path $directory.FullName 'python.exe') }
    foreach ($candidate in ($candidates | Select-Object -Unique)) {
        $found = Test-Python $candidate
        if ($found) { return $found }
    }
    return $null
}

function Ensure-Seal {
    $rule = Get-NetFirewallRule -Name 'NovaLabStart-MasterSeal' -ErrorAction SilentlyContinue
    if ($rule) {
        $rule | Set-NetFirewallRule -Enabled True -Direction Inbound -Action Block -Profile Any
        $rule | Get-NetFirewallAddressFilter | Set-NetFirewallAddressFilter -LocalAddress Any -RemoteAddress Any
        $rule | Get-NetFirewallPortFilter | Set-NetFirewallPortFilter -Protocol TCP -LocalPort 445,8080,8443
    } else {
        New-NetFirewallRule -Name 'NovaLabStart-MasterSeal' -DisplayName 'NovaLab master seal until clone configuration' -Group 'NovaLabStart' -Direction Inbound -Action Block -Protocol TCP -LocalPort 445,8080,8443 -RemoteAddress Any -Profile Any | Out-Null
    }
}

if (-not $IsolatedLabVM) { throw 'Ten skrypt jest przeznaczony tylko dla odizolowanej VM szkoleniowej.' }
if (-not [Environment]::Is64BitProcess -or $PSVersionTable.PSEdition -ne 'Desktop') { throw 'Uruchom Windows PowerShell 5.1 x64 jako administrator (powershell.exe).' }
if ($SysprepShutdown -and $ShutdownWhenReady) { throw 'Wybierz tylko jeden tryb wylaczenia.' }
$os = Get-CimInstance Win32_OperatingSystem
$computer = Get-CimInstance Win32_ComputerSystem
if ($os.ProductType -ne 1 -or [int]$os.BuildNumber -lt 22000) { throw 'Wymagany Windows 11 x64.' }
if ($computer.PartOfDomain) { throw 'Wzorzec nie moze byc czlonkiem domeny.' }
$up = @(Get-NetAdapter | Where-Object Status -eq 'Up')
if ($up.Count -ne 1) { throw 'Pozostaw jedna aktywna karte podlaczona do wydzielonego segmentu labu.' }
$adapter = $up[0]
if ($LabAdapterName -and $adapter.Name -ne $LabAdapterName) { throw 'Nazwa jedynej aktywnej karty nie zgadza sie z -LabAdapterName.' }
if (Get-NetRoute | Where-Object DestinationPrefix -in @('0.0.0.0/0','::/0')) { throw 'Wykryto trase domyslna. Odlacz NAT/bridge i usun brame w odizolowanej VM przed uruchomieniem.' }
if (Get-NetFirewallProfile | Where-Object { -not $_.Enabled }) { throw 'Wlacz zapore dla wszystkich profili.' }
if (Test-Path (Join-Path $env:ProgramData 'NovaLab36')) { throw 'Wczesniejszy NovaLab36 wymaga usuniecia jego wlasnym deinstalatorem.' }
$resume = $false
if (Test-Path -LiteralPath $labRoot) {
    if ((Get-Item -LiteralPath $labRoot -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Katalog labu nie moze byc laczem ani junction.' }
    $marker = Join-Path $labRoot 'installed.json'
    if (-not (Test-Path -LiteralPath $marker)) { throw 'Istnieje katalog labu bez poprawnego markera. Uzyj czystego obrazu.' }
    $existing = Get-Content -LiteralPath $marker -Raw | ConvertFrom-Json
    if ($existing.product -ne 'NovaLabStart-v2' -or $existing.root -ne $labRoot -or -not $existing.PSObject.Properties['master_sealed'] -or -not $existing.master_sealed) {
        throw 'To jest zwykla instalacja lub starszy lab. Uzyj czystego wzorca albo jego oryginalnego deinstalatora; konta nie beda nadpisane.'
    }
    if (-not $existing.PSObject.Properties['master_payload_sha256'] -or $existing.master_payload_sha256 -ne $expectedSha256) { throw 'Wzorzec pochodzi z innej wersji skryptu. Nie bedzie nadpisany.' }
    $resume = $true
} else {
    foreach ($i in 1..6) {
        $name = 'user{0:00}' -f $i
        if (Get-LocalUser -Name $name -ErrorAction SilentlyContinue) { throw "Konto $name juz istnieje. Skrypt nie zmieni jego hasla ani uprawnien." }
    }
    if (Get-LocalGroup -Name NovaLabStudents -ErrorAction SilentlyContinue) { throw 'Grupa NovaLabStudents juz istnieje.' }
    if (Get-SmbShare -Name NovaLabStart -ErrorAction SilentlyContinue) { throw 'Udzial NovaLabStart juz istnieje.' }
    if (Get-NetFirewallRule -Group NovaLabStart -ErrorAction SilentlyContinue) { throw 'Reguly NovaLabStart juz istnieja.' }
}
if (Get-CimInstance Win32_Process | Where-Object { $_.Name -like 'python*' -and $_.CommandLine -like "*$labRoot\app\server.py*" }) { throw 'Zatrzymaj aplikacje Ctrl+C przed przygotowaniem wzorca.' }
foreach ($port in @(8080,8443)) {
    if (Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue) { throw "Port $port jest zajety. Zatrzymaj proces, ktory go uzywa." }
}
$python = Find-Python
$installer = $null
if (-not $python) {
    if (-not $PythonInstallerPath) { throw 'Brak Python 3.11+ x64 dla wszystkich uzytkownikow. Zainstaluj go albo podaj -PythonInstallerPath do klasycznego instalatora EXE offline.' }
    $installer = (Get-Item -LiteralPath $PythonInstallerPath -ErrorAction Stop).FullName
    if ([IO.Path]::GetExtension($installer) -ne '.exe') { throw 'Obslugiwany jest klasyczny instalator Python EXE x64, nie MSIX ani instalator menedzera.' }
    $signature = Get-AuthenticodeSignature -LiteralPath $installer
    if ($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notmatch 'Python Software Foundation') { throw 'Instalator nie ma poprawnego podpisu Python Software Foundation.' }
}
$archiveBytes = [Convert]::FromBase64String($embeddedArchive)
if ((Get-BytesHash $archiveBytes) -ne $expectedSha256) { throw 'Blad integralnosci osadzonego archiwum.' }
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$memory = [IO.MemoryStream]::new($archiveBytes,$false)
$archive = [IO.Compression.ZipArchive]::new($memory,[IO.Compression.ZipArchiveMode]::Read,$true)
try {
    $prefix = [IO.Path]::GetFullPath($stage).TrimEnd('\') + '\'
    foreach ($entry in $archive.Entries) {
        $targetPath = [IO.Path]::GetFullPath((Join-Path $stage $entry.FullName))
        if (-not $targetPath.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)) { throw 'Nieprawidlowa sciezka w archiwum.' }
    }
    if ($CheckOnly) {
        [pscustomobject]@{Tryb='Tylko kontrola, bez zmian';System=$os.Caption;Build=$os.BuildNumber;Karta=$adapter.Name;PlanowanyIP="$templateIP/24";Python=if($python){$python.exe}else{'Zostanie zainstalowany z podanego EXE'};Konta='user01-user06, standardowe';Dane='5 zadan, takie same na wszystkich Windowsach';Kali='Bez zmian';ArchiwumSHA256=$expectedSha256;Wznowienie=$resume} | Format-List
        return
    }
    if (Test-Path -LiteralPath $stage) {
        if ((Get-Item -LiteralPath $stage -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'Katalog pakietu nie moze byc laczem ani junction.' }
        if (-not (Test-Path -LiteralPath (Join-Path $stage 'payload.sha256')) -or (Get-Content (Join-Path $stage 'payload.sha256') -Raw).Trim() -ne $expectedSha256) { throw 'Katalog roboczy juz istnieje i ma inne dane. Nie bedzie nadpisany.' }
        foreach ($entry in $archive.Entries) {
            if (-not $entry.Name) { continue }
            $stream = $entry.Open()
            $copy = [IO.MemoryStream]::new()
            try { $stream.CopyTo($copy); $digest = Get-BytesHash -Bytes ($copy.ToArray()) } finally { $copy.Dispose();$stream.Dispose() }
            $file = Join-Path $stage $entry.FullName
            if (-not (Test-Path -LiteralPath $file) -or (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $digest) { throw "Zmieniony plik pakietu: $file" }
        }
    } else {
        New-Item -ItemType Directory -Path $stage | Out-Null
        foreach ($entry in $archive.Entries) {
            if (-not $entry.Name) { continue }
            $file = Join-Path $stage $entry.FullName
            New-Item -ItemType Directory -Path (Split-Path $file -Parent) -Force | Out-Null
            [IO.Compression.ZipFileExtensions]::ExtractToFile($entry,$file,$false)
        }
        Set-Content -LiteralPath (Join-Path $stage 'payload.sha256') -Encoding ASCII -Value $expectedSha256
    }
} finally { $archive.Dispose();$memory.Dispose() }

if (-not $python) {
    $targetDir = Join-Path $env:ProgramFiles 'NovaLabPython'
    $arguments = @('/quiet','InstallAllUsers=1','PrependPath=0','Include_test=0','Include_launcher=0',('TargetDir="'+$targetDir+'"'))
    $process = Start-Process -FilePath $installer -ArgumentList $arguments -Wait -PassThru
    if ($process.ExitCode -eq 3010) { throw 'Python zainstalowany. Uruchom ponownie Windows i powtorz skrypt przed tworzeniem kont.' }
    if ($process.ExitCode -ne 0) { throw "Instalator Python zakonczyl sie kodem $($process.ExitCode)." }
    $python = Find-Python
    if (-not $python) { throw 'Nie znaleziono poprawnego Python x64 po instalacji.' }
}
$package = Join-Path $stage 'NovaLab_Start'
$environment = Join-Path $package '00_SRODOWISKO'
$before = [ordered]@{utc=[DateTime]::UtcNow.ToString('o');adapter=$adapter.Name;ipv4=@(Get-NetIPAddress -InterfaceIndex $adapter.ifIndex -AddressFamily IPv4 | Select-Object IPAddress,PrefixLength,PrefixOrigin);dns=@(Get-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -AddressFamily IPv4 | Select-Object ServerAddresses);server_service=(Get-Service LanmanServer).Status.ToString()}
$before | ConvertTo-Json -Depth 6 | Set-Content (Join-Path $stage ('sieci-przed-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss')+'.json')) -Encoding UTF8
Set-NetIPInterface -InterfaceIndex $adapter.ifIndex -AddressFamily IPv4 -Dhcp Disabled
$ips = @(Get-NetIPAddress -InterfaceIndex $adapter.ifIndex -AddressFamily IPv4)
if ($ips.Count -ne 1 -or $ips[0].IPAddress -ne $templateIP -or $ips[0].PrefixLength -ne 24) {
    foreach ($ip in $ips) { Remove-NetIPAddress -InputObject $ip -Confirm:$false }
    New-NetIPAddress -InterfaceIndex $adapter.ifIndex -IPAddress $templateIP -PrefixLength 24 | Out-Null
}
Set-DnsClientServerAddress -InterfaceIndex $adapter.ifIndex -ResetServerAddresses
Set-Service -Name LanmanServer -StartupType Automatic
Start-Service -Name LanmanServer
if (-not $resume) {
    & (Join-Path $environment 'windows\Install-Start.ps1') -IsolatedLabVM -Station 1 -TemplateMode -PythonExe $python.exe
}
Ensure-Seal
. (Join-Path $labRoot 'windows\Common.ps1')
Assert-Isolation $templateIP '10.60.0.11'
$state = Read-LabState
$cfgPath = Join-Path $labRoot 'config.json'
$cfg = Get-Content -LiteralPath $cfgPath -Raw | ConvertFrom-Json
$cfg.station = 0
$cfg.windows_ip = $templateIP
$cfg.kali_ip = '10.60.0.11'
$cfg | Add-Member -NotePropertyName is_master -NotePropertyValue $true -Force
foreach ($property in $cfg.fixed.PSObject.Properties) { $property.Value = $false }
$cfg | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $cfgPath -Encoding UTF8
$state.station = 0
$state.windows_name = 'MASTER-NOT-ASSIGNED'
$state.windows_ip = $templateIP
$state.python = $python.exe
$state | Add-Member -NotePropertyName master_sealed -NotePropertyValue $true -Force
$state | Add-Member -NotePropertyName master_payload_sha256 -NotePropertyValue $expectedSha256 -Force
$state | ConvertTo-Json -Depth 6 | Set-Content (Join-Path $labRoot 'installed.json') -Encoding UTF8
$adminGroup = Get-LocalGroup -SID 'S-1-5-32-544'
$admins = @(Get-LocalGroupMember -Group $adminGroup)
$students = @(Get-LocalGroupMember -Group NovaLabStudents)
foreach ($i in 1..6) {
    $user = Get-LocalUser -Name ('user{0:00}' -f $i)
    if (-not $user.Enabled -or -not ($students | Where-Object SID -eq $user.SID) -or ($admins | Where-Object SID -eq $user.SID)) { throw 'Nieprawidlowe uprawnienia kont uczestnikow.' }
}
$webAccounts = Get-Content (Join-Path $labRoot 'accounts.json') -Raw | ConvertFrom-Json
$expectedUsers = @(1..6 | ForEach-Object { 'user{0:00}' -f $_ })
if (Compare-Object -ReferenceObject $expectedUsers -DifferenceObject @($webAccounts.PSObject.Properties.Name)) { throw 'Nieprawidlowy zestaw kont WEB.' }
$report = [ordered]@{status='PREPARED_SEALED';utc=[DateTime]::UtcNow.ToString('o');computer_name=$env:COMPUTERNAME;template_ip="$templateIP/24";python=$python.exe;python_version=$python.version;users=@($state.users.name);web_accounts=6;task_datasets=5;ports_blocked_until_clone=@(445,8080,8443);kali_accounts_changed=$false;package=$package;payload_sha256=$expectedSha256;clone_command='powershell.exe -NoProfile -ExecutionPolicy Bypass -File C:\ProgramData\NovaLabStart\windows\Finalize-Clone.ps1 -Station N';sysprep_requested=[bool]$SysprepShutdown}
$reportFile = Join-Path $labRoot 'MASTER-RAPORT.json'
$report | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $reportFile -Encoding UTF8
Write-Host "Wzorzec przygotowany. Raport: $reportFile"
Write-Host 'Adres wzorca: 10.60.0.254/24. Porty cwiczen sa zablokowane. Aplikacja nie ma autostartu.'
Write-Host 'Klonuj obraz po uogolnieniu i wylaczeniu. Klony konfiguruj pojedynczo, aby nie powielac .254.'
Write-Host 'Po OOBE na kazdym klonie: Finalize-Clone.ps1 -Station 1..6 jako administrator, potem restart.'
if ($SysprepShutdown) {
    Write-Host 'Uruchamianie Sysprep /generalize /oobe /shutdown. W razie bledu sprawdz Windows\System32\Sysprep\Panther.'
    $sysprep = Start-Process -FilePath "$env:SystemRoot\System32\Sysprep\Sysprep.exe" -ArgumentList '/generalize','/oobe','/shutdown' -Wait -PassThru
    if ($sysprep.ExitCode -ne 0) { throw "Sysprep zakonczyl sie kodem $($sysprep.ExitCode). Nie klonuj; sprawdz logi Panther." }
} elseif ($ShutdownWhenReady) {
    Write-Host 'Zwykle wylaczenie; nie wykonano generalizacji Sysprep.'
    Stop-Computer -Force
} else {
    Write-Host 'Skrypt nie wylaczyl komputera. Po sprawdzeniu raportu uruchom go ponownie z -SysprepShutdown.'
}
